-- IPA FY2024 SG public questions (15 questions).
-- Official question paper and answer key:
-- https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf
-- https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_ans.pdf
INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2024-01','exam-sg','リスクマネジメント','standard','single_choice','【2024年度 IPA公開問題 問1】JIS Q 31000:2019におけるリスクアセスメントを構成するプロセスの組合せはどれか。','[{"id":"a","text":"リスク特定、リスク評価、リスク受容"},{"id":"b","text":"リスク特定、リスク分析、リスク評価"},{"id":"c","text":"リスク分析、リスク対応、リスク受容"},{"id":"d","text":"リスク分析、リスク評価、リスク対応"}]','"b"','リスクアセスメントはリスク特定、リスク分析、リスク評価から構成される。リスク対応はアセスメント後のプロセス。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-02','exam-sg','情報資産管理','standard','single_choice','【2024年度 IPA公開問題 問2】社外秘情報の持出しを禁じ、従業員に周知して、不正持出し時に「社外秘とは知らなかった」という言い訳をさせないことも目的とする対策はどれか。','[{"id":"a","text":"権限のない従業員が文書にアクセスできないようにするペーパレス化"},{"id":"b","text":"信頼関係の維持を目的とした職場環境の整備"},{"id":"c","text":"電子メールの外部送信データ量の制限"},{"id":"d","text":"情報の管理レベルについてのラベル付け"}]','"d"','機密区分のラベル付けにより、情報の取扱基準と機密性を明示でき、利用者にルールを認識させやすい。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-03','exam-sg','マルウェア対策','standard','single_choice','【2024年度 IPA公開問題 問3】マルウェアの検出方法のうち、検査対象のプログラムを実行する必要があるものはどれか。','[{"id":"a","text":"コンペア法"},{"id":"b","text":"チェックサム法"},{"id":"c","text":"パターンマッチング法"},{"id":"d","text":"ビヘイビア法"}]','"d"','ビヘイビア法はプログラムを実行した際の振る舞いを観察して検出する。ほかの方法は主にデータやパターンを比較する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-04','exam-sg','サイバー攻撃','standard','single_choice','【2024年度 IPA公開問題 問4】サイバーキルチェーンに関する説明として、適切なものはどれか。','[{"id":"a","text":"委託先の情報セキュリティリスクが委託元にも影響するという考え方に基づくリスク分析"},{"id":"b","text":"通信を中継してクライアントとサーバが直接通信しているように装い、情報を盗聴する攻撃"},{"id":"c","text":"攻撃者の視点から、攻撃の手口を偵察から目的実行までの段階に分けたもの"},{"id":"d","text":"取引データを時系列につなげて保存し、改ざんを検知可能にする仕組み"}]','"c"','サイバーキルチェーンは攻撃活動を偵察、武器化、配送、侵入、実行などの段階に分けて理解するモデル。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-05','exam-sg','認証技術','standard','single_choice','【2024年度 IPA公開問題 問5】リスクベース認証の説明として、適切なものはどれか。','[{"id":"a","text":"画面上の点を正しい順序で一筆書きになぞってロックを解除する。"},{"id":"b","text":"通常と異なるIPアドレスやWebブラウザから認証要求があった場合に追加認証を行う。"},{"id":"c","text":"認証局がサーバ証明書発行時に組織の実在性などを確認する。"},{"id":"d","text":"ゆがんだ文字を含む画像の文字を正しく入力させる。"}]','"b"','リスクベース認証は、接続元や端末、行動などのリスクに応じて追加の認証を求める。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-06','exam-sg','TLS・証明書','standard','single_choice','【2024年度 IPA公開問題 問6】PCがTLSでWebサーバにアクセスし、サーバ証明書を入手した後、認証局の公開鍵を利用して行う動作はどれか。','[{"id":"a","text":"通信に利用する共通鍵を認証局の公開鍵で復号する。"},{"id":"b","text":"共通鍵を生成し、認証局の公開鍵で暗号化する。"},{"id":"c","text":"サーバ証明書の正当性を認証局の公開鍵で検証する。"},{"id":"d","text":"利用者が送信する秘匿データを認証局の公開鍵で暗号化する。"}]','"c"','認証局の公開鍵は、証明書に付された署名を検証して証明書の正当性を確認するために使う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-07','exam-sg','個人情報保護','standard','single_choice','【2024年度 IPA公開問題 問7】個人情報保護法が保護対象としている個人情報に関する記述のうち、適切なものはどれか。','[{"id":"a","text":"企業が管理する顧客情報に限られる。"},{"id":"b","text":"個人が秘密にしているプライバシー情報に限られる。"},{"id":"c","text":"生存する個人に関する情報に限られる。"},{"id":"d","text":"日本国籍を有する個人に関する情報に限られる。"}]','"c"','個人情報保護法上の個人情報は生存する個人に関する情報が対象であり、顧客情報や秘密情報だけに限定されない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-08','exam-sg','内部統制','standard','single_choice','【2024年度 IPA公開問題 問8】内部統制の基本的要素の一つである「統制活動」に該当するものはどれか。','[{"id":"a","text":"経営目的を達成するための経営方針及び経営戦略"},{"id":"b","text":"個人情報保護に関する脅威と脆弱性の分析"},{"id":"c","text":"受注から出荷に至る業務プロセスに組み込まれた処理結果の検証"},{"id":"d","text":"定期的に計画して実施する内部業務監査"}]','"c"','統制活動は、承認、照合、検証など、リスクに対応するため業務プロセスに組み込まれた具体的な統制手続を指す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-09','exam-sg','システム信頼性','standard','single_choice','【2024年度 IPA公開問題 問9】RASISのA（可用性）を向上させるものはどれか。MTBFは平均故障間隔、MTTRは平均修復時間を表す。','[{"id":"a","text":"MTBFとMTTRをともに2倍にする。"},{"id":"b","text":"MTBFは変えず、MTTRを2倍にする。"},{"id":"c","text":"MTBFを2倍にし、MTTRは変えない。"},{"id":"d","text":"MTBFを半分にし、MTTRを2倍にする。"}]','"c"','可用性は概ねMTBF/(MTBF+MTTR)。MTBFを伸ばしMTTRを維持すると稼働率が上がる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-10','exam-sg','ネットワークセキュリティ','standard','single_choice','【2024年度 IPA公開問題 問10】社内ネットワークからインターネットへのアクセスを中継し、Webコンテンツをキャッシュして高速化し、セキュリティ確保にも利用されるものはどれか。','[{"id":"a","text":"DMZ"},{"id":"b","text":"IPマスカレード（NAPT）"},{"id":"c","text":"ファイアウォール"},{"id":"d","text":"プロキシサーバ"}]','"d"','プロキシサーバはクライアントの代わりに外部へアクセスし、キャッシュやアクセス制御、ログ取得に利用できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-11','exam-sg','RPA・業務改善','standard','single_choice','【2024年度 IPA公開問題 問11】全社的な推進体制でRPAを導入するときの留意点として、適切なものはどれか。','[{"id":"a","text":"各業務部門が連携し、対象業務のプロセス全体を可視化・見直しした上で導入する。"},{"id":"b","text":"画面変更が多い業務から優先して導入する。"},{"id":"c","text":"情報システム部門などと連携せず、各業務部門だけで選定・運用する。"},{"id":"d","text":"例外処理が多く条件が複雑な業務を優先する。"}]','"a"','RPA導入前に業務全体を可視化して標準化し、関係部門と連携する。頻繁に変わる画面や複雑な例外処理は自動化の難度が高い。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-12','exam-sg','品質管理','standard','single_choice','【2024年度 IPA公開問題 問12】特性要因図を説明したものはどれか。','[{"id":"a","text":"原因と結果の関係を魚の骨のような形に整理し、結果に関係する原因を明確にする。"},{"id":"b","text":"時系列データを折れ線グラフで表し、管理限界線で管理する。"},{"id":"c","text":"データを区間に分類し、各区間の個数を棒グラフにする。"},{"id":"d","text":"項目を出現頻度順に棒グラフで並べ、累積和を折れ線で示す。"}]','"a"','特性要因図（魚の骨図）は、結果に影響する要因を体系的に洗い出して整理する図。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-13','exam-sg','多要素認証','standard','single_choice','【2024年度 IPA公開問題 問13】社内限定だったSaaSをテレワークで社外からも利用可能にする。IPアドレス制限を無効化する一方、不正ログイン対策を強化するための設定変更はどれか。','[{"id":"a","text":"機能1（IP制限）を無効化し、機能4（ワンタイムパスワード）を有効化する。"},{"id":"b","text":"機能1を無効化し、機能5（CAPTCHA）を有効化する。"},{"id":"c","text":"機能2（ID・パスワード認証）を無効化し、機能4を有効化する。"},{"id":"d","text":"機能2を無効化し、機能5を有効化する。"},{"id":"e","text":"機能3（複雑なパスワード）を無効化し、機能4を有効化する。"},{"id":"f","text":"機能3を無効化し、機能5を有効化する。"}]','"a"','社外アクセスを可能にするには社内IP限定を解除し、認証強化にはCAPTCHAよりもワンタイムパスワードを有効にする。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-14','exam-sg','バックアップ・事業継続','standard','single_choice','【2024年度 IPA公開問題 問14】顧客DBは毎週日曜にフル、他の日に増分バックアップを取得し、1週間保存する。火曜のテープが物理破損し、金曜に論理破損が発生した。テープ破損も想定した再発防止策として最も効果が高いものはどれか。','[{"id":"a","text":"DBMSをIaaS上で稼働させ、データベースもIaaSに格納する。"},{"id":"b","text":"データベースのレプリケーションを行いコピーを確保する。"},{"id":"c","text":"DB格納ディスクをRAID5構成にする。"},{"id":"d","text":"テープに加え、NASにもバックアップを1週間分保存する。"},{"id":"e","text":"毎日システムを停止してフルバックアップを取得する。"}]','"d"','論理破損したデータをレプリケーションで複製すると破損も反映される可能性がある。別媒体・別保管先にバックアップを持つことでテープ障害にも備えられる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-2024-15','exam-sg','偽警告・マルウェア対策','standard','single_choice','【2024年度 IPA公開問題 問15】ブラウザにマルウェア感染の警告画面が表示されたが、正規の対策ソフトによるものではないと判明した。従業員に周知すべき対応はどれか。','[{"id":"a","text":"警告の指示に従い、直ちに指定ツールをインストールする。"},{"id":"b","text":"警告の指示には従わず、直ちにWebブラウザを終了する。"},{"id":"c","text":"競合を避けるため正規の対策ソフトを削除して指定ツールを入れる。"},{"id":"d","text":"警告に表示された電話番号へ連絡し、指示に従う。"},{"id":"e","text":"ロゴが正規製品と同じなら、指定ツールをインストールする。"}]','"b"','偽警告（サポート詐欺）の指示、電話番号、ダウンロードには従わず、ブラウザを閉じて社内窓口へ報告する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja');
